@php use App\Infrastructure\Docker\Yaml; @endphp
# Generated by Mini Forge for {{ $site->domain }}. Changes here are overwritten
# on the next apply or deploy.
name: {!! Yaml::string($site->slug) !!}

x-logging: &logging
  driver: local
  options:
    max-size: "10m"
    max-file: "3"

# Every service runs the same release image. Code lives in the image; only
# storage/ is a volume, and .env is mounted read-only.
x-app: &app
  image: {!! Yaml::string($image) !!}
  restart: unless-stopped
  volumes:
    - storage:/app/storage
    # Long syntax: if .env is missing, Docker refuses to start instead of
    # creating an empty directory in its place.
    - type: bind
      source: ./.env
      target: /app/.env
      read_only: true
      bind:
        create_host_path: false
  networks: [default, data]
  logging: *logging

services:
@foreach ($services as $service)
@if ($service->role === \App\Enums\ServiceRole::Web)
  web:
    <<: *app
    networks: [default, data, proxy]
    labels:
      traefik.enable: "true"
      traefik.docker.network: {!! Yaml::string($network) !!}
      traefik.http.routers.{{ $site->slug }}.rule: {!! Yaml::string('Host(`'.$site->domain.'`)') !!}
      traefik.http.routers.{{ $site->slug }}.entrypoints: websecure
      traefik.http.services.{{ $site->slug }}.loadbalancer.server.port: "8080"
@if ($service->command)
    command: {!! Yaml::string($service->command) !!}
@endif
    healthcheck:
      test: ["CMD", "curl", "-fsS", "-o", "/dev/null", {!! Yaml::string('http://127.0.0.1:8080'.$site->health_check_path) !!}]
      interval: 10s
      timeout: 5s
      retries: 3
      start_period: 30s
    mem_limit: {{ $service->memory_limit ?: '512m' }}
@elseif ($service->role === \App\Enums\ServiceRole::Worker)
  worker:
    <<: *app
    command: {!! Yaml::string($service->command ?: 'php artisan queue:work --sleep=3 --tries=3 --max-time=3600') !!}
    stop_grace_period: 60s
    healthcheck:
      disable: true
    mem_limit: {{ $service->memory_limit ?: '384m' }}
@elseif ($service->role === \App\Enums\ServiceRole::Scheduler)
  scheduler:
    <<: *app
    command: {!! Yaml::string($service->command ?: 'php artisan schedule:work') !!}
    healthcheck:
      disable: true
    mem_limit: {{ $service->memory_limit ?: '256m' }}
@endif
@endforeach

networks:
  proxy:
    name: {!! Yaml::string($network) !!}
    external: true
  data:
    name: {!! Yaml::string($dataNetwork) !!}
    external: true

volumes:
  storage:
